actions.script:
const fixed = ec.context.get('projectTabId') || null
const projectOptions = fixed ? [] : Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').call()?.projectList || [])
// in ProjectDetail's tab the project is its workEffortId even when the user may not see it (then "not available")
let project = fixed || rootWorkEffortId || workEffortId || null
if (!project) {
    const mine = Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.get#ProjectOptions').parameters({memberOnly: true}).call()?.projectList || [])
    project = mine[0]?.key || projectOptions[0]?.key || null
}
if (!project) { ec.web.sendJsonResponse({projectOptions: projectOptions, noProject: true}); return }
const out = ec.service.sync().name('ironstone.projects.PlanningServices.get#Backlog').parameters({rootWorkEffortId: project, assigneePartyId: assigneePartyId || null,
    purposeEnumId: purposeEnumId || null, labelId: labelId || null, componentId: componentId || null, epicId: epicId || null, text: text || null}).call() || {}
if (ec.message.hasError()) { ec.message.clearErrors(); ec.web.sendJsonResponse({projectOptions: projectOptions, notAvailable: true, rootWorkEffortId: project}); return }
ec.web.sendJsonResponse({backlog: out.backlog, projectOptions: projectOptions, projectFixed: !!fixed})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.rank#BacklogItems').parameters({rootWorkEffortId: ec.context.get('projectTabId') || rootWorkEffortId || workEffortId || '',
    workEffortIds: workEffortIds || '', sprintWorkEffortId: sprintWorkEffortId || null, previousWorkEffortId: previousWorkEffortId || null,
    nextWorkEffortId: nextWorkEffortId || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {doneCount: out.doneCount, messageInfos: [{type: out.failedCount ? 'warning' : 'success', message: out.message}]})

const project = ec.context.get('projectTabId') || rootWorkEffortId || workEffortId || ''
const out = ec.service.sync().name('ironstone.projects.WorkItemServices.quickAdd#WorkItem').parameters({rootWorkEffortId: project, workEffortName: workEffortName || '',
    purposeEnumId: purposeEnumId || null, sprintWorkEffortId: sprintWorkEffortId || null}).call() || {}
if (!ec.message.hasError() && nextWorkEffortId) ec.service.sync().name('mantle.work.TaskServices.set#TaskBacklogRank').parameters({workEffortId: out.workEffortId,
    nextWorkEffortId: nextWorkEffortId}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {workEffortId: out.workEffortId, messageInfos: [{type: 'success', message: out.message, link: out.url}]})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.save#Sprint').parameters({rootWorkEffortId: ec.context.get('projectTabId') || rootWorkEffortId || workEffortId || null,
    workEffortId: sprintWorkEffortId || null, workEffortName: workEffortName ?? null, description: description ?? null, startDay: startDay || null,
    endDay: endDay || null, capacity: capacity ?? ''}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {sprintWorkEffortId: out.workEffortId, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.start#Sprint').parameters({workEffortId: sprintWorkEffortId || '', description: description ?? null,
    startDay: startDay || null, endDay: endDay || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {started: true, messageInfos: [{type: 'success', message: out.message}]})

const out = ec.service.sync().name('ironstone.projects.PlanningServices.complete#Sprint').parameters({workEffortId: sprintWorkEffortId || '', carryTo: carryTo || 'next',
    newSprintName: newSprintName || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {completed: true, carriedToSprintId: out.carriedToSprintId, messageInfos: [{type: 'success', message: out.message}]})

render-mode.text:
${JSON.stringify([{t: "dynamicContainer", id: "BacklogTui",
                url: sri.buildUrl("//Projects/WorkItems/BacklogTui").addParameters({rootWorkEffortId: ec.context.get("projectTabId")
                    || (ec.context.get("inProjectDetail") ? ec.context.get("workEffortId") : null) || rootWorkEffortId || null}).getUrlWithParams()}])}
